   [46]={next_id=47, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="就像这根线，尽管它看起来脆弱，却是锚点空间中唯一普遍的存在。无论是那些类人生物、还是过往骑士的残魂，甚至那两个追杀我们的骑士残躯，它们都和这丝线有关系。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
