   [145]={next_id=146, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所以天兆之星的真正目的——它要将所有离散的封禁物碎片尽数融合，同化她们各自的锚点空间，最终构筑起独属于自己的、最庞大的锚点空间！", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
